pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // Heuristic refinement: 12 is a tighter threshold for modern item distributions.
    if post_residual > 0 && post_residual < 12 {
        score += 65.0 * (12.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits, prioritize the bin.
    // Enhanced: Reward more if the post_residual matches the next_item_size exactly (Perfect Fit).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Penalize placements that block the next item significantly
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Open Bin Pressure: Discourage new bins.
    // If this is a new bin, apply dynamic penalty based on the number of existing open bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 120.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Density Balancing: Favor bins that keep the mean residual low.
    // Use a non-linear penalty for deviating from the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // 5. Progress Sensitivity & Late Stage Consolidation:
    // As we approach the end of the stream, increase the pressure to close bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.75 {
        if post_residual == 0 {
            score -= 50.0;
        }
        if bin_residual == bin_capacity {
            score += 80.0 * progress;
        }
    }

    // 6. Efficiency Guard: If only one bin can fit the item, ensure it's picked.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Fragmentation Control (Evolved)
    // Heavier penalties for new bins to force deeper search into open bins.
    if is_new_bin {
        let base_penalty = 110.0;
        let density_penalty = (open_bins_count as f64 * 0.35) + (progress * 50.0);
        score += base_penalty + density_penalty;

        if fitting_bins_count > 0 {
            // Non-linear penalty scaling based on available fitting options.
            score += 180.0 + (fitting_bins_count as f64 * 25.0).powf(1.1);
        }
    }

    // 2. Predictive Lookahead Optimization (Refined)
    // Calculate "dead space" risk more aggressively.
    if next_item_size > 0 {
        let fit_margin = post_residual as i32 - next_item_size as i32;
        if fit_margin < 0 {
            // Severe penalty for creating an impossible fit for the next item.
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward "Goldilocks" residuals that favor future fit.
            let synergy = 12.0 / (fit_margin as f64 + 1.0);
            score -= synergy;
            // Additional reward if the residual is perfectly sized for the next item.
            if fit_margin == 0 { score -= 20.0; }
        }
    }

    // 3. Dynamic Residual Balancing
    // Target a tighter residual to encourage packing efficiency.
    let target = bin_capacity as f64 * 0.08;
    let deviation = (post_residual as f64 - target).abs();
    score += deviation * 0.40;

    // 4. Critical Path Scarcity
    // Prioritize closing the gap on bins that are almost sealed.
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 75.0;
        }
        // Penalize bins that are too empty to be useful.
        if post_residual > (bin_capacity * 2 / 3) {
            score += 10.0;
        }
    }

    // 5. Late-Stage Consolidation
    // In the final 15% of the stream, prioritize finishing off bins.
    if progress > 0.85 {
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual < (bin_capacity / 6) {
            score -= 40.0;
        }
    }

    // 6. Efficiency Guard for Small Items
    // Prevent small items from triggering new bins unless absolutely necessary.
    if is_new_bin && item_size < (bin_capacity / 6) {
        score += 65.0;
    }

    score
}
